// Find open, unassigned Priority 1 incidents
// older than 24 hours, reassign each to a
// fallback group, and return how many were
// reassigned — avoiding every Lesson 16 pitfall.

var cutoff = gs.hoursAgo(24);
var gr = new GlideRecord('incident');
gr.addQuery('active', true);
gr.addQuery('priority', 1);
gr.addNullQuery('assigned_to');
gr.addQuery('sys_created_on', '<', cutoff);
gr.query();

var reassignedCount = 0;
while (gr.next()) {
    gr.setValue('assignment_group', fallbackGroupSysId);
    gr.work_notes = 'Auto-reassigned: unassigned P1 > 24h.';
    gr.update();
    reassignedCount++;
}
return reassignedCount;
